INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4536173, 652882, 26845, '<td valign="top">Physical Graffiti</td>', 'Physical Graffiti', '2008-03-03 19:00:26.000000', NULL, 1),
(4536191, 653729, 56754, '<td valign="top">Great exposure on the sky, though the selective desaturation might not have worked completely in your favor in relevance to the song lyric you have chosen.  The lights that still have color aren''t exactly the lights from the city, but that is honestly my only complaint.<br/> <br/>You really balanced out the exposure well to capture great detail in the clouds, and still have those awesome streaks of light from passing cars.  This is one of my favorites for this challenge!</td>', 'Great exposure on the sky, though the selective desaturation might not have worked completely in your favor in relevance to the song lyric you have chosen.  The lights that still have color aren''t exactly the lights from the city, but that is honestly my only complaint. You really balanced out the exposure well to capture great detail in the clouds, and still have those awesome streaks of light from passing cars.  This is one of my favorites for this challenge!', '2008-03-03 19:12:28.000000', NULL, 1),
(4536192, 653582, 56754, '<td valign="top">Such a witty capture!  The exposure is perfect on the booths, and you did a good job in bringing out the weathered details, especially on the front one.</td>', 'Such a witty capture!  The exposure is perfect on the booths, and you did a good job in bringing out the weathered details, especially on the front one.', '2008-03-03 19:14:07.000000', NULL, 1),
(4536194, 652783, 56754, '<td valign="top">Eery, and such an excellent way to play with the title you''ve chosen.  The tilted composition and shallow depth of field were a great choice.</td>', 'Eery, and such an excellent way to play with the title you''ve chosen.  The tilted composition and shallow depth of field were a great choice.', '2008-03-03 19:15:34.000000', NULL, 1),
(4536198, 652917, 56754, '<td valign="top">Not sure if you were trying to achieve the halo effect on purpose, and it is a bit distracting, but the contrast and colors of your image have such a great impact on the age of the car, and the desolate surroundings.<br/> <br/>It might need just a bit more relevance between the lyric you chose to the mood you''ve created in the image, but overall, this really works for me!  7</td>', 'Not sure if you were trying to achieve the halo effect on purpose, and it is a bit distracting, but the contrast and colors of your image have such a great impact on the age of the car, and the desolate surroundings. It might need just a bit more relevance between the lyric you chose to the mood you''ve created in the image, but overall, this really works for me!  7', '2008-03-03 19:18:03.000000', NULL, 1),
(4536201, 653212, 56754, '<td valign="top">This image is exquisitely cropped- perfect distance between the palm trees to the top and bottom of the photo, and the color sets a wonderful, serene mood.  Very well done, one of my favorites!</td>', 'This image is exquisitely cropped- perfect distance between the palm trees to the top and bottom of the photo, and the color sets a wonderful, serene mood.  Very well done, one of my favorites!', '2008-03-03 19:22:31.000000', NULL, 1),
