(4538690, 653738, 89940, '<td valign="top">Lovely model, great pose, the DOF really works well. On my first pass I rated this a 7 but when I came through on my second pass to comment I couldn''t really find anything I would change, so I''m bumping my score up.</td>', 'Lovely model, great pose, the DOF really works well. On my first pass I rated this a 7 but when I came through on my second pass to comment I couldn''t really find anything I would change, so I''m bumping my score up.', '2008-03-04 21:37:43.000000', NULL, 1),
(4538721, 653351, 33672, '<td valign="top">Excellent idea! and one of my favorite zep tunes!</td>', 'Excellent idea! and one of my favorite zep tunes!', '2008-03-04 21:46:53.000000', NULL, 1),
(4538722, 653587, 33672, '<td valign="top">Nice job using the backdrop/mural. Gives the real feel of that song.</td>', 'Nice job using the backdrop/mural. Gives the real feel of that song.', '2008-03-04 21:48:09.000000', NULL, 1),
(4538725, 653582, 33672, '<td valign="top">Perfect for theme. Nice job.</td>', 'Perfect for theme. Nice job.', '2008-03-04 21:48:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4538726, 653009, 33672, '<td valign="top">Too funny! Very original!</td>', 'Too funny! Very original!', '2008-03-04 21:49:42.000000', NULL, 1),
(4538728, 653829, 33672, '<td valign="top">Incredible land/seascape that has the real spirit of the song.</td>', 'Incredible land/seascape that has the real spirit of the song.', '2008-03-04 21:50:21.000000', NULL, 1),
(4538731, 653439, 33672, '<td valign="top">Well you settled something I''ve beeen wondering for all the years since I first heard that song! Great shot for the theme. Very original.</td>', 'Well you settled something I''ve beeen wondering for all the years since I first heard that song! Great shot for the theme. Very original.', '2008-03-04 21:51:45.000000', NULL, 1),
(4538732, 653839, 33672, '<td valign="top">Beautiful Still life.</td>', 'Beautiful Still life.', '2008-03-04 21:51:59.000000', NULL, 1),
(4538739, 653713, 33672, '<td valign="top">Though I may have to put you down for a while....Funny catch. I''ve always been a fan of grafitti</td>', 'Though I may have to put you down for a while....Funny catch. I''ve always been a fan of grafitti', '2008-03-04 21:54:31.000000', NULL, 1),
(4538740, 653729, 45187, '<td valign="top">fantastically dramatic image</td>', 'fantastically dramatic image', '2008-03-04 21:54:39.000000', NULL, 1),
(4538747, 651429, 33672, '<td valign="top">That phone belongs in a museum. Great idea and execution.</td>', 'That phone belongs in a museum. Great idea and execution.', '2008-03-04 21:55:45.000000', NULL, 1),
(4538774, 653677, 70661, '<td valign="top">One of my favs. Love it! Already gave you a 9, just back to comment.</td>', 'One of my favs. Love it! Already gave you a 9, just back to comment.', '2008-03-04 22:03:44.000000', NULL, 1),
(4538823, 653473, 86799, '<td valign="top">Nicely done.  The streak across the sun is a nice touch...good catch.</td>', 'Nicely done.  The streak across the sun is a nice touch...good catch.', '2008-03-04 22:16:07.000000', NULL, 1),
(4538837, 653587, 86799, '<td valign="top">I like it, good interpretation...but...it almost looks a little "Mary Poppins"ish...which is pretty absurd for Zeppelin.  But again, I do like it.  It''s just...a little fluffy. HaHaHa.</td>', 'I like it, good interpretation...but...it almost looks a little "Mary Poppins"ish...which is pretty absurd for Zeppelin.  But again, I do like it.  It''s just...a little fluffy. HaHaHa.', '2008-03-04 22:18:40.000000', NULL, 1),
(4538855, 653738, 86799, '<td valign="top">O.K. interpretation, and cool picture.  But "Immigrant Song" is pretty fierce and very dramatic, blasting.  She''s kinda pretty, certainly not fierce, looks more like she''s on the runway.</td>', 'O.K. interpretation, and cool picture.  But "Immigrant Song" is pretty fierce and very dramatic, blasting.  She''s kinda pretty, certainly not fierce, looks more like she''s on the runway.', '2008-03-04 22:22:50.000000', NULL, 1),
(4538874, 653800, 86799, '<td valign="top">Bizarre.  Very striking photograph, but not sure how this illustrates or interprets the song.  It''s cool, though.</td>', 'Bizarre.  Very striking photograph, but not sure how this illustrates or interprets the song.  It''s cool, though.', '2008-03-04 22:28:37.000000', NULL, 1),
(4538880, 653227, 86799, '<td valign="top">Well done.  Great quality and detail.</td>', 'Well done.  Great quality and detail.', '2008-03-04 22:30:59.000000', NULL, 1),
(4538888, 653717, 86799, '<td valign="top">Yeah, that''s right.  Not proper and civil, let''s make a mess!</td>', 'Yeah, that''s right.  Not proper and civil, let''s make a mess!', '2008-03-04 22:33:01.000000', NULL, 1),
(4538901, 652741, 86799, '<td valign="top">Very illustrative.  "having a nervous breakdown...drive me insaaaaannnnnne".  I like this one.  Tense.  Good work.</td>', 'Very illustrative.  "having a nervous breakdown...drive me insaaaaannnnnne".  I like this one.  Tense.  Good work.', '2008-03-04 22:35:33.000000', NULL, 1),
(4538924, 653816, 86799, '<td valign="top">"Used to sing on the mountains, but the mountains washed away"...now they''re just hills.  I like this one.  Well done.</td>', '"Used to sing on the mountains, but the mountains washed away"...now they''re just hills.  I like this one.  Well done.', '2008-03-04 22:40:55.000000', NULL, 1),
(4538930, 653454, 86799, '<td valign="top">Nice pic, but she doesn''t look much dazed or confused.</td>', 'Nice pic, but she doesn''t look much dazed or confused.', '2008-03-04 22:42:03.000000', NULL, 1),
(4538938, 653654, 86799, '<td valign="top">Simple and elegant.  Fits the flavor of the song well, IMO.</td>', 'Simple and elegant.  Fits the flavor of the song well, IMO.', '2008-03-04 22:43:47.000000', NULL, 1),
(4538950, 653815, 86799, '<td valign="top">Looks better that Plant does, too, HAR!  But can the dog still sing???  Nice shot.  Cool dog.</td>', 'Looks better that Plant does, too, HAR!  But can the dog still sing???  Nice shot.  Cool dog.', '2008-03-04 22:46:12.000000', NULL, 1),
(4538962, 653829, 86799, '<td valign="top">Cool.  Goes well with the song, good L.Z. tone and flavor.</td>', 'Cool.  Goes well with the song, good L.Z. tone and flavor.', '2008-03-04 22:47:47.000000', NULL, 1),
(4538973, 653565, 86799, '<td valign="top">Yeah.  The mystery and drama of "Black Mountain Side", right there.  Nice.</td>', 'Yeah.  The mystery and drama of "Black Mountain Side", right there.  Nice.', '2008-03-04 22:50:29.000000', NULL, 1),
(4538995, 653815, 10818, '<td valign="top">Your dog has aged quite gracefully. Grey hair just makes us more distinctive.  :)</td>', 'Your dog has aged quite gracefully. Grey hair just makes us more distinctive.  :)', '2008-03-04 22:57:15.000000', NULL, 1),
(4538998, 653462, 10818, '<td valign="top">Poor Tom indeed.  Looks like a mug shot from a really hard night.</td>', 'Poor Tom indeed.  Looks like a mug shot from a really hard night.', '2008-03-04 22:58:20.000000', NULL, 1),
(4539002, 653541, 10818, '<td valign="top">Great lighting from the window.  Interesting and works well.</td>', 'Great lighting from the window.  Interesting and works well.', '2008-03-04 22:59:20.000000', NULL, 1),
(4539009, 652917, 10818, '<td valign="top">That is just fantastic.  The colors of the the sky, car and brush are fabulous.</td>', 'That is just fantastic.  The colors of the the sky, car and brush are fabulous.', '2008-03-04 23:01:41.000000', NULL, 1),
(4539011, 653677, 10818, '<td valign="top">Excellent shot.  Love the colors of the dresses and shirts.  Quite festive and fun.</td>', 'Excellent shot.  Love the colors of the dresses and shirts.  Quite festive and fun.', '2008-03-04 23:03:10.000000', NULL, 1),
(4539497, 653818, 22459, '<td valign="top">Love the border....the image is good too!</td>', 'Love the border....the image is good too!', '2008-03-05 01:25:40.000000', NULL, 1),
(4539673, 653818, 34741, '<td valign="top">beautiful</td>', 'beautiful', '2008-03-05 03:42:02.000000', NULL, 1),
(4539783, 652633, 88616, '<td valign="top">At first glance this looked really good. But the hair/blur is very distracting.</td>', 'At first glance this looked really good. But the hair/blur is very distracting.', '2008-03-05 05:13:50.000000', NULL, 1),
(4539832, 653623, 22459, '<td valign="top">Great colors, great subject matter and great title works well......if you need any help with the schoolin...well I''m available!!!</td>', 'Great colors, great subject matter and great title works well......if you need any help with the schoolin...well I''m available!!!', '2008-03-05 06:10:04.000000', NULL, 1),
(4539833, 653253, 22459, '<td valign="top">Nice work, the hi-key works well.</td>', 'Nice work, the hi-key works well.', '2008-03-05 06:10:51.000000', NULL, 1),
(4539836, 653769, 22459, '<td valign="top">This is a unique image, not sure that it works well with so much going on but it is different! that is a bonus here at DPC. For my taste this is mid- range so a 5 from me.</td>', 'This is a unique image, not sure that it works well with so much going on but it is different! that is a bonus here at DPC. For my taste this is mid- range so a 5 from me.', '2008-03-05 06:13:48.000000', NULL, 1),
(4540141, 653603, 78064, '<td valign="top">Love it.</td>', 'Love it.', '2008-03-05 09:31:43.000000', NULL, 1),
(4540166, 653829, 31606, '<td valign="top">One of my favorites.  I love how dreamy it looks</td>', 'One of my favorites.  I love how dreamy it looks', '2008-03-05 09:44:56.000000', NULL, 1),
(4540167, 652186, 31606, '<td valign="top">Very nice capture.  In my top three.</td>', 'Very nice capture.  In my top three.', '2008-03-05 09:45:14.000000', NULL, 1),
(4540170, 653669, 31606, '<td valign="top">Love the perspective.</td>', 'Love the perspective.', '2008-03-05 09:45:46.000000', NULL, 1),
(4540286, 653299, 32767, '<td valign="top">The rock structure kinda looks like the Prescence thing</td>', 'The rock structure kinda looks like the Prescence thing', '2008-03-05 10:24:05.000000', NULL, 1),
(4540291, 652500, 32767, '<td valign="top">What a beautiful shot but for that damn fence. I think you could have cloned that out in Advanced...if you wanted to clone it out, of course.</td>', 'What a beautiful shot but for that damn fence. I think you could have cloned that out in Advanced...if you wanted to clone it out, of course.', '2008-03-05 10:25:30.000000', NULL, 1),
(4540301, 653839, 32767, '<td valign="top">Nice image but it doesn''t honestly relate to the lyrics or spirit of the song, IMO.</td>', 'Nice image but it doesn''t honestly relate to the lyrics or spirit of the song, IMO.', '2008-03-05 10:27:17.000000', NULL, 1),
(4540304, 651155, 32767, '<td valign="top">Killer shot. Needs more "Hop" though. Kidding...kidding...</td>', 'Killer shot. Needs more "Hop" though. Kidding...kidding...', '2008-03-05 10:28:02.000000', NULL, 1),
(4540314, 653792, 32767, '<td valign="top">Nice shot...great make-up but your Devil doesn''t look the least bit scary or beckoning. Good Luck!</td>', 'Nice shot...great make-up but your Devil doesn''t look the least bit scary or beckoning. Good Luck!', '2008-03-05 10:29:44.000000', NULL, 1),
(4540318, 653410, 32767, '<td valign="top">Looks like coffee, to me. Kidding...kidding. Beautiful image, perfect shadow work. Good Luck!<br/><br/><i>Message edited by author 2008-03-16 04:28:07.</i></td>', 'Looks like coffee, to me. Kidding...kidding. Beautiful image, perfect shadow work. Good Luck!', '2008-03-05 10:30:50.000000', '2008-03-16 04:28:07.000000', 1),
(4540321, 653297, 32767, '<td valign="top">Tangerines, for sure but no real relation to the song.</td>', 'Tangerines, for sure but no real relation to the song.', '2008-03-05 10:31:23.000000', NULL, 1),
(4540324, 653669, 32767, '<td valign="top">Awesome vibe and very Seaside-ish. One of my faves in the Challenge</td>', 'Awesome vibe and very Seaside-ish. One of my faves in the Challenge', '2008-03-05 10:32:07.000000', NULL, 1),
(4540332, 653253, 32767, '<td valign="top">Really nice image. Good Luck!</td>', 'Really nice image. Good Luck!', '2008-03-05 10:33:31.000000', NULL, 1),
(4540341, 652390, 32767, '<td valign="top">This is great. You nicely captured the vibe of the song.</td>', 'This is great. You nicely captured the vibe of the song.', '2008-03-05 10:36:16.000000', NULL, 1),
(4540357, 653818, 32767, '<td valign="top">Nice interpretation of the song and a beautiful image.<br/> <br/>"I never thought it would ever go. I cursed the gloom that set upon us... <br/>But I know that I love you so"</td>', 'Nice interpretation of the song and a beautiful image. "I never thought it would ever go. I cursed the gloom that set upon us... But I know that I love you so"', '2008-03-05 10:40:26.000000', NULL, 1),
(4540525, 653763, 91063, '<td valign="top">I was starting to get worried noone did tangerine, my all time favorite. Thanks! Very simplistic and classic.</td>', 'I was starting to get worried noone did tangerine, my all time favorite. Thanks! Very simplistic and classic.', '2008-03-05 11:34:05.000000', NULL, 1),
(4540579, 653825, 89940, '<td valign="top">I like the clouds and the overall gold color cast. I find the image as a whole a uninteresting. There is no clear subject (just an empty field).</td>', 'I like the clouds and the overall gold color cast. I find the image as a whole a uninteresting. There is no clear subject (just an empty field).', '2008-03-05 11:50:19.000000', NULL, 1),
(4540585, 653667, 89940, '<td valign="top">The foreground tree is a little soft. It''s the first thing that caught my eye and made me think the whole photo was soft. The composition is OK but I like the photo better if I crop out the left most tree even though it shows less river.</td>', 'The foreground tree is a little soft. It''s the first thing that caught my eye and made me think the whole photo was soft. The composition is OK but I like the photo better if I crop out the left most tree even though it shows less river.', '2008-03-05 11:53:03.000000', NULL, 1),
(4540589, 653763, 89940, '<td valign="top">The color on the Tangerine is great but the rinds are so blown and without contrast against the background that it''s hard to tell what it is.</td>', 'The color on the Tangerine is great but the rinds are so blown and without contrast against the background that it''s hard to tell what it is.', '2008-03-05 11:54:00.000000', NULL, 1),
(4540590, 652500, 89940, '<td valign="top">My initial thought when I saw this photo was it is uninteresting. Looking more I''m thinking it''s because the foreground cliff keeps drawing my eye instead of the water or background cliff. Perhaps cropping a little more of the right edge?</td>', 'My initial thought when I saw this photo was it is uninteresting. Looking more I''m thinking it''s because the foreground cliff keeps drawing my eye instead of the water or background cliff. Perhaps cropping a little more of the right edge?', '2008-03-05 11:55:31.000000', NULL, 1),
(4540594, 653834, 89940, '<td valign="top">Would be so much better with better focus on the shark. My eye is drawn to to the light first and then to the shark. Lightening the bottom of the shark so it stands out a little more might be better.</td>', 'Would be so much better with better focus on the shark. My eye is drawn to to the light first and then to the shark. Lightening the bottom of the shark so it stands out a little more might be better.', '2008-03-05 11:56:36.000000', NULL, 1),
(4540596, 653471, 89940, '<td valign="top">Nice lighting, the bread looks great. In fact I think it''s the best photo I''ve ever seen of a hot dog but having said that it really does nothing for me.</td>', 'Nice lighting, the bread looks great. In fact I think it''s the best photo I''ve ever seen of a hot dog but having said that it really does nothing for me.', '2008-03-05 11:57:30.000000', NULL, 1),
(4540598, 653769, 89940, '<td valign="top">This is a very busy photo and the subject in this photo is the lady not the dog. The dog is so small in comparison that I didn''t even notice it until I read the title.</td>', 'This is a very busy photo and the subject in this photo is the lady not the dog. The dog is so small in comparison that I didn''t even notice it until I read the title.', '2008-03-05 11:58:45.000000', NULL, 1),
(4540602, 653829, 39090, '<td valign="top">I love the mystical feeling here.  This photo had the most Zeppelin "feel" to it out of the rest.</td>', 'I love the mystical feeling here.  This photo had the most Zeppelin "feel" to it out of the rest.', '2008-03-05 11:59:56.000000', NULL, 1),
(4540603, 652390, 89940, '<td valign="top">Nice photo. I like the lighting on the girl''s face. It bothers me that the top of her head is cut off.</td>', 'Nice photo. I like the lighting on the girl''s face. It bothers me that the top of her head is cut off.', '2008-03-05 12:00:18.000000', NULL, 1),
(4540606, 653831, 89940, '<td valign="top">I like the way the background looks tilted. Think it might be a little better if the cat wasn''t so dead center, so it looks like it is about to run into the photo. The background in general doesn''t work well because it''s too close to the color of the cat. Not so much a problem in the background but in the foreground and right under the cat it''s hard to tell which is cat and which is background</td>', 'I like the way the background looks tilted. Think it might be a little better if the cat wasn''t so dead center, so it looks like it is about to run into the photo. The background in general doesn''t work well because it''s too close to the color of the cat. Not so much a problem in the background but in the foreground and right under the cat it''s hard to tell which is cat and which is background', '2008-03-05 12:02:34.000000', NULL, 1),
(4540608, 652596, 89940, '<td valign="top">I like the soft lighting on her face. The ear rings catch my eye but then turn me off because they are out of focus. There are also some weird rainbow artifacts in the hair.</td>', 'I like the soft lighting on her face. The ear rings catch my eye but then turn me off because they are out of focus. There are also some weird rainbow artifacts in the hair.', '2008-03-05 12:04:02.000000', NULL, 1),
(4540611, 653253, 89940, '<td valign="top">I like the perspective and color. Wish the DOF was a little deeper so the back part of the car was a little sharper.</td>', 'I like the perspective and color. Wish the DOF was a little deeper so the back part of the car was a little sharper.', '2008-03-05 12:05:48.000000', NULL, 1),
(4540613, 653716, 89940, '<td valign="top">I like the concept. The lighting on the coins is not the greatest. The silver coins are not shiny enough and the penny is too shiny. Tough thing to get right. <br/> <br/>My eye is immediately drawn to the penny because of the reflections and then when I look over at the other coins they look a little flat.</td>', 'I like the concept. The lighting on the coins is not the greatest. The silver coins are not shiny enough and the penny is too shiny. Tough thing to get right.  My eye is immediately drawn to the penny because of the reflections and then when I look over at the other coins they look a little flat.', '2008-03-05 12:08:09.000000', NULL, 1),
(4540665, 653791, 66709, '<td valign="top">disqualify outside the dates (1973)  Can you prove you goes back into time to take the picture last week!  then I can give you a 10</td>', 'disqualify outside the dates (1973)  Can you prove you goes back into time to take the picture last week!  then I can give you a 10', '2008-03-05 12:28:43.000000', NULL, 1),
(4541290, 653738, 46821, '<td valign="top">Geðveik mynd og já það er best að vera "from the land of the ice and snow".. <br/> <br/>Efast ekki um að þú vinnir</td>', 'Geðveik mynd og já það er best að vera "from the land of the ice and snow"..  Efast ekki um að þú vinnir', '2008-03-05 16:22:44.000000', NULL, 1),
(4541354, 653738, 7756, '<td valign="top">Should win</td>', 'Should win', '2008-03-05 16:56:50.000000', NULL, 1),
(4541714, 653253, 65234, '<td valign="top">Nice color contrast, a bit blurry but the graffiti is clear.</td>', 'Nice color contrast, a bit blurry but the graffiti is clear.', '2008-03-05 19:39:24.000000', NULL, 1),
(4541721, 653738, 65234, '<td valign="top">She''s a little underdressed for the ice and snow!  And seems strangely disconnected from the background.  Great shot overall, though, and the lyric is from one of my more favorite LZ songs.</td>', 'She''s a little underdressed for the ice and snow!  And seems strangely disconnected from the background.  Great shot overall, though, and the lyric is from one of my more favorite LZ songs.', '2008-03-05 19:42:51.000000', NULL, 1),
(4541726, 652882, 65234, '<td valign="top">Looks a lot more like the Physical Graffiti cover.  Suits that quite well, actually.</td>', 'Looks a lot more like the Physical Graffiti cover.  Suits that quite well, actually.', '2008-03-05 19:45:54.000000', NULL, 1),
(4541729, 653726, 65234, '<td valign="top">Nice color and reflections.  Crop is a little tight on top, and you need some juice being squeezed ;-)</td>', 'Nice color and reflections.  Crop is a little tight on top, and you need some juice being squeezed ;-)', '2008-03-05 19:47:15.000000', NULL, 1),
(4541732, 653637, 65234, '<td valign="top">OK; different take on the concept but I''ll buy it.  Good choice of background to get the graffiti on a wall, sorta''.</td>', 'OK; different take on the concept but I''ll buy it.  Good choice of background to get the graffiti on a wall, sorta''.', '2008-03-05 19:48:34.000000', NULL, 1),
(4541739, 653796, 65234, '<td valign="top">My first daffodil just started to open today!  Not an exciting shot but nice color and a pleasant sight for those of us just waiting for spring.</td>', 'My first daffodil just started to open today!  Not an exciting shot but nice color and a pleasant sight for those of us just waiting for spring.', '2008-03-05 19:50:22.000000', NULL, 1),
(4541743, 653535, 65234, '<td valign="top">Wow; that''s sharp!  Looks like a grand time is being had by the boy and the birds, and that beach looks mighty inviting.</td>', 'Wow; that''s sharp!  Looks like a grand time is being had by the boy and the birds, and that beach looks mighty inviting.', '2008-03-05 19:51:42.000000', NULL, 1),
(4541748, 653682, 65234, '<td valign="top">Effective use of color to draw my eye to the steaming cup.  And I actually like the border :-)</td>', 'Effective use of color to draw my eye to the steaming cup.  And I actually like the border :-)', '2008-03-05 19:54:09.000000', NULL, 1),
(4541758, 653683, 65234, '<td valign="top">I like the concept (that is definitely a perfect candy store rock!), but I''m not sure about the yellow/orange hue on the model.  Maybe I need to go ingest something chemical so I can appreciate some deeper meaning to the color.</td>', 'I like the concept (that is definitely a perfect candy store rock!), but I''m not sure about the yellow/orange hue on the model.  Maybe I need to go ingest something chemical so I can appreciate some deeper meaning to the color.', '2008-03-05 19:56:01.000000', NULL, 1),
(4541764, 653599, 65234, '<td valign="top">There''s a smile in the tea :-)  Not sure what the object up in the corner is or what it brings to the composition.</td>', 'There''s a smile in the tea :-)  Not sure what the object up in the corner is or what it brings to the composition.', '2008-03-05 19:57:17.000000', NULL, 1),
(4541771, 653610, 65234, '<td valign="top">Different sort of seaside from what I''m used to; the colors in the boats add a lot of vibrancy.  Interesting mix with the new-looking boats and peeling paint.</td>', 'Different sort of seaside from what I''m used to; the colors in the boats add a lot of vibrancy.  Interesting mix with the new-looking boats and peeling paint.', '2008-03-05 19:59:30.000000', NULL, 1),
(4541772, 653677, 65234, '<td valign="top">Nice movement in this.</td>', 'Nice movement in this.', '2008-03-05 19:59:55.000000', NULL, 1),
(4541779, 652594, 65234, '<td valign="top">Long shadows are appropriately mood-setting.</td>', 'Long shadows are appropriately mood-setting.', '2008-03-05 20:01:45.000000', NULL, 1),
(4541791, 653804, 65234, '<td valign="top">Uh, OK, I get it.  But that looks a lot like the opener on a can of Spam ... easy open ... I don''t think I want to pursue this train of thought.</td>', 'Uh, OK, I get it.  But that looks a lot like the opener on a can of Spam ... easy open ... I don''t think I want to pursue this train of thought.', '2008-03-05 20:06:05.000000', NULL, 1),
(4541796, 653676, 65234, '<td valign="top">Can''t quite tell what I''m looking at so, yeah, I''m confused.  Ooh; I just spotted a bunny in the lower left!  Now I''m starting to look at this as a Rorshach test ;-)</td>', 'Can''t quite tell what I''m looking at so, yeah, I''m confused.  Ooh; I just spotted a bunny in the lower left!  Now I''m starting to look at this as a Rorshach test ;-)', '2008-03-05 20:08:41.000000', NULL, 1),
