(4542185, 653471, 9763, '<td valign="top">A bit grainy with blueish tinge.  I think you could light the hot dog from the front too to add to the product photography feel.  It''s not an exciting photo, even though the composition is nice.  Dress up the background and add some personality.</td>', 'A bit grainy with blueish tinge.  I think you could light the hot dog from the front too to add to the product photography feel.  It''s not an exciting photo, even though the composition is nice.  Dress up the background and add some personality.', '2008-03-05 23:07:42.000000', NULL, 1),
(4542187, 653834, 9763, '<td valign="top">Dark, blurry, not really representing the ocean.  It''s focused more on the shark.  Reshoot.  :)</td>', 'Dark, blurry, not really representing the ocean.  It''s focused more on the shark.  Reshoot.  :)', '2008-03-05 23:08:09.000000', NULL, 1),
(4542190, 653297, 9763, '<td valign="top">The color is a bit off, too magenta.  Perhaps light from the sides.  Also, the fruit doesn''t look very pleasing.  Overexposing may help or softer lighting.</td>', 'The color is a bit off, too magenta.  Perhaps light from the sides.  Also, the fruit doesn''t look very pleasing.  Overexposing may help or softer lighting.', '2008-03-05 23:08:53.000000', NULL, 1),
