(4546865, 653582, 22301, '<td valign="top">I like the last telephone booth facing directly at me as if it is bringing to my attention the problems it has on its back.</td>', 'I like the last telephone booth facing directly at me as if it is bringing to my attention the problems it has on its back.', '2008-03-07 21:57:08.000000', NULL, 1),
(4546869, 653822, 22301, '<td valign="top">I really like the light.</td>', 'I really like the light.', '2008-03-07 21:58:46.000000', NULL, 1),
