(4546887, 653738, 26001, '<td valign="top">Larus, you do realize that almost everyone is going to recognize you, right? Absolutely stunning portrait. everything is perfect except her right hand feels a bit unnatural/uncomfortable. although in this cold temperature, you can only admire model''s ability to deliver this pose in these clothes.</td>', 'Larus, you do realize that almost everyone is going to recognize you, right? Absolutely stunning portrait. everything is perfect except her right hand feels a bit unnatural/uncomfortable. although in this cold temperature, you can only admire model''s ability to deliver this pose in these clothes.', '2008-03-07 22:08:48.000000', NULL, 1),
(4546929, 653535, 77724, '<td valign="top">love the color</td>', 'love the color', '2008-03-07 22:40:49.000000', NULL, 1),
(4546944, 653541, 48697, '<td valign="top">Great b&amp;w, love the lighting, well done!</td>', 'Great b&w, love the lighting, well done!', '2008-03-07 22:51:05.000000', NULL, 1),
(4546948, 653565, 48697, '<td valign="top">Very nice b&amp;w, love the backlite snow blowing in the wind.</td>', 'Very nice b&w, love the backlite snow blowing in the wind.', '2008-03-07 22:54:26.000000', NULL, 1),
(4546955, 653802, 48697, '<td valign="top">Nicely done, I like the fallen angel feel to this and well one lighting. I''m not to fonf of teh dark vignette on the right of the frame but still a great pic!</td>', 'Nicely done, I like the fallen angel feel to this and well one lighting. I''m not to fonf of teh dark vignette on the right of the frame but still a great pic!', '2008-03-07 22:57:46.000000', NULL, 1),
