(4546967, 652783, 48697, '<td valign="top">I like the DOF you used in this shot.</td>', 'I like the DOF you used in this shot.', '2008-03-07 23:04:17.000000', NULL, 1),
(4546970, 652741, 48697, '<td valign="top">Cool shot! I really like the lighting setup and I defintely get the feeling they are having a communication breakdown, well done!</td>', 'Cool shot! I really like the lighting setup and I defintely get the feeling they are having a communication breakdown, well done!', '2008-03-07 23:08:12.000000', NULL, 1),
