INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4547318, 653404, 48697, '<td valign="top">I feel that the hard vignette around the girl is a bit too much.</td>', 'I feel that the hard vignette around the girl is a bit too much.', '2008-03-08 02:07:46.000000', NULL, 1),
