(4547544, 653462, 70875, '<td valign="top">That''s a rough face, but what I noticed is the very pale eyes compared to it.</td>', 'That''s a rough face, but what I noticed is the very pale eyes compared to it.', '2008-03-08 04:59:52.000000', NULL, 1),
(4547564, 653738, 90495, '<td valign="top">Interesting. Well photographed. When I look at her feet I feel cold. Is that snow on her toes?</td>', 'Interesting. Well photographed. When I look at her feet I feel cold. Is that snow on her toes?', '2008-03-08 05:48:44.000000', NULL, 1),
(4547567, 653084, 90495, '<td valign="top">Shouldn''t the emphasis be on the bend? My eyes are drawn back to the bush when I look at the road.</td>', 'Shouldn''t the emphasis be on the bend? My eyes are drawn back to the bush when I look at the road.', '2008-03-08 05:51:47.000000', NULL, 1),
(4547568, 653834, 90495, '<td valign="top">Frankly, this looks like an aquarium shot and not the ocean you are trying to portray.</td>', 'Frankly, this looks like an aquarium shot and not the ocean you are trying to portray.', '2008-03-08 05:53:59.000000', NULL, 1),
(4547569, 653454, 90495, '<td valign="top">She looks like a model posing for a nude, not dazed, nor confused. Well photographed and the comp is good. Shallow dof was used nicely.</td>', 'She looks like a model posing for a nude, not dazed, nor confused. Well photographed and the comp is good. Shallow dof was used nicely.', '2008-03-08 05:57:23.000000', NULL, 1),
