(4547678, 653802, 86799, '<td valign="top">Not sure about the positioning of the "wing".  The angle of it makes us question what it is...  Nice misty feeling.  Nice overall, just needs some adjustment of pose, I think.</td>', 'Not sure about the positioning of the "wing".  The angle of it makes us question what it is...  Nice misty feeling.  Nice overall, just needs some adjustment of pose, I think.', '2008-03-08 07:22:00.000000', NULL, 1),
(4547679, 653283, 86799, '<td valign="top">Classic!  Nice interpretation.</td>', 'Classic!  Nice interpretation.', '2008-03-08 07:23:52.000000', NULL, 1),
(4547683, 653764, 86799, '<td valign="top">O.K., fits well, but...not a lot of interest.  Good quality image of hiker on a hill overlooking the highway.  Just missing the drama of the song.  Don''t see the "aching in my heart", I guess.</td>', 'O.K., fits well, but...not a lot of interest.  Good quality image of hiker on a hill overlooking the highway.  Just missing the drama of the song.  Don''t see the "aching in my heart", I guess.', '2008-03-08 07:27:09.000000', NULL, 1),
(4547691, 652594, 86799, '<td valign="top">The markers are too small for "impact".  The ones on the left are lost in the background.  Nice idea.  I''d look for a different angle to keep the big tree, but bring the bright wihite markers more into prominence.</td>', 'The markers are too small for "impact".  The ones on the left are lost in the background.  Nice idea.  I''d look for a different angle to keep the big tree, but bring the bright wihite markers more into prominence.', '2008-03-08 07:29:51.000000', NULL, 1),
