(4547703, 653667, 86799, '<td valign="top">Nice photo, but needs some Led Zeppelin impact.</td>', 'Nice photo, but needs some Led Zeppelin impact.', '2008-03-08 07:34:58.000000', NULL, 1),
(4547704, 653611, 86799, '<td valign="top">Nice, but needs some Led Zeppelin impact.</td>', 'Nice, but needs some Led Zeppelin impact.', '2008-03-08 07:35:26.000000', NULL, 1),
(4547707, 653009, 86799, '<td valign="top">Funny, wry.</td>', 'Funny, wry.', '2008-03-08 07:37:33.000000', NULL, 1),
(4547709, 653623, 86799, '<td valign="top">A little light and airy for such a psychedelic shout for raw burning love.  Pretty, though.</td>', 'A little light and airy for such a psychedelic shout for raw burning love.  Pretty, though.', '2008-03-08 07:40:35.000000', NULL, 1),
(4547711, 653236, 86799, '<td valign="top">Other than the title, this one is more reminiscent of a Broadway musical than a LZ song.</td>', 'Other than the title, this one is more reminiscent of a Broadway musical than a LZ song.', '2008-03-08 07:42:40.000000', NULL, 1),
(4547712, 652967, 86799, '<td valign="top">O.K., nice quality, lighting, sharpness, etc...but missing interest, illustration of LZ song.</td>', 'O.K., nice quality, lighting, sharpness, etc...but missing interest, illustration of LZ song.', '2008-03-08 07:43:48.000000', NULL, 1),
(4547714, 653253, 86799, '<td valign="top">O.K., but needs some drama, some interest.  The graffiti here is just kinda normal old everyday graffiti.</td>', 'O.K., but needs some drama, some interest.  The graffiti here is just kinda normal old everyday graffiti.', '2008-03-08 07:45:12.000000', NULL, 1),
(4547717, 653602, 86799, '<td valign="top">I like this better now that I''ve looked at it again.  Kinda grows on me.  Dramatic and mysterious and "Zep"ish.  Gotta raise it up a point...or two.</td>', 'I like this better now that I''ve looked at it again.  Kinda grows on me.  Dramatic and mysterious and "Zep"ish.  Gotta raise it up a point...or two.', '2008-03-08 07:47:41.000000', NULL, 1),
