(4547721, 653684, 86799, '<td valign="top">O.K. pic, but needs some LZ impact, some drama or intrigue.</td>', 'O.K. pic, but needs some LZ impact, some drama or intrigue.', '2008-03-08 07:49:43.000000', NULL, 1),
(4547725, 652596, 86799, '<td valign="top">It''s a little bit too light and fluffy to go well with that song, IMO.  Nice pic, though.  Her cheek has a little washout &amp; roughness.</td>', 'It''s a little bit too light and fluffy to go well with that song, IMO.  Nice pic, though.  Her cheek has a little washout & roughness.', '2008-03-08 07:52:18.000000', NULL, 1),
