(4556114, 652882, 50641, '<td valign="top">Congrats on the ribbon!  You got the tones just perfect.  I had no idea this site was still available for capture, good stinkin on your part!</td>', 'Congrats on the ribbon!  You got the tones just perfect.  I had no idea this site was still available for capture, good stinkin on your part!', '2008-03-11 21:10:47.000000', NULL, 0),
